/* Seal the desktop shared lib: export only the Fila* C API and the JNI entry points;
   filament::/utils:: C++ internals stay local to avoid symbol clashes with other libs in
   the host process. macOS twin: -exported_symbol in CMakeLists.txt. */
{
    global:
        Fila*;
        Java_*;
        JNI_OnLoad;
    local:
        *;
};
